<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Validation\ValidationException;
class CobrosCreditInstallmentComponent extends Model { public const KINDS=['principal_refinanced','principal_new','interest_current','interest_refinanced']; protected $fillable=['credit_id','installment_id','kind','original_amount','applied_amount','source_credit_id','source_renewal_id']; protected function casts():array{return ['original_amount'=>'decimal:4','applied_amount'=>'decimal:4'];} protected static function booted():void{static::saving(function(self $c):void{if(!in_array($c->kind,self::KINDS,true))throw ValidationException::withMessages(['kind'=>'Tipo no permitido.']);if(bccomp((string)$c->original_amount,'0',4)<0||bccomp((string)$c->applied_amount,'0',4)<0||bccomp((string)$c->applied_amount,(string)$c->original_amount,4)>0)throw ValidationException::withMessages(['amount'=>'Importe inválido.']);$i=CobrosCreditInstallment::find($c->installment_id);$credit=CobrosCredit::find($c->credit_id);if(!$credit||!$i||(int)$i->credit_id!==(int)$c->credit_id)throw ValidationException::withMessages(['installment_id'=>'Componente fuera del crédito.']);});} public function credit():BelongsTo{return $this->belongsTo(CobrosCredit::class);} public function installment():BelongsTo{return $this->belongsTo(CobrosCreditInstallment::class,'installment_id');} }
